css:
.frames {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 12px;
  max-width: 420px;
  padding: 16px;
}

.frame {
  width: 100%;
  aspect-ratio: 2 / 3;
  object-fit: cover;
  border-radius: 8px;
}

.pos-left {
  object-position: left;
}

.pos-center {
  object-position: center;
}

.pos-right {
  object-position: right;
}
